import { useEffect, useState } from 'react';

import {
  ADMIN_PORTAL_HEADER_HEIGHT_PX,
  STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX,
} from './constants';

const toOffsetPx = (navigationHeight: number) =>
  ADMIN_PORTAL_HEADER_HEIGHT_PX + navigationHeight;

export const useStickyNavigationTopOffset = (
  navigationTestId: string,
): string => {
  const [offsetPx, setOffsetPx] = useState(
    STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX,
  );

  useEffect(() => {
    const navigationElement = document.querySelector<HTMLElement>(
      `[data-testid="${navigationTestId}"]`,
    );

    if (!navigationElement) {
      return;
    }

    const updateOffset = () => {
      setOffsetPx(toOffsetPx(navigationElement.offsetHeight));
    };

    updateOffset();

    const resizeObserver = new ResizeObserver(updateOffset);
    resizeObserver.observe(navigationElement);

    return () => {
      resizeObserver.disconnect();
    };
  }, [navigationTestId]);

  return `${offsetPx}px`;
};
